$${\rm{M}}{{\rm{D}}_{{\rm{Change}}}}\ ={\rm{M}}{{\rm{D}}_{{\rm{Final}}}}{\rm{-M}}{{\rm{D}}_{{\rm{Baseline}}}}$$
\end{document}
