$$S{D_{Change}=\ }\sqrt S {D^2}_{Baseline}\ +S{D^2}_{Final} - {\rm{ }}\left({2 \times R \times S{D_{Baseline}} \times S{D_{Final}}} \right),{\rm{ }}R\ =0.5$$
\end{document}
